#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
"""Before / after figure for one node: the structural rule (every storing subscription callback -> every publishing callback /
timer of the node, drawn as join or state edges until 2026-10-25) against the evidence-based task set (an edge only with an
evidence record; the rest reported as candidates, never drawn as edges).

The "before" set is reconstructed exactly: the model marks candidate=True on precisely the pairs the structural rule used to turn
into edges, so before = candidates ∪ evidence edges of the node, now = evidence edges only.

usage: join_before_after.py <fish_tasks.json> --node <substring> [--node <substring> ...] -o <prefix>"""
import argparse, collections, html, json, os, subprocess, sys

INK, INK2, MUTED, GRID, SURF = '#1a1a19', '#4b4a45', '#8a897f', '#e1e0d9', '#ffffff'
BLUE, RED, GREEN, AMBER = '#2a78d6', '#d93a36', '#1baf7a', '#e08a00'
BW, BH, GX, GY, PADX, PADY = 250, 34, 230, 8, 30, 70
NOCAND = False      # --no-candidates: NOW panels without candidate lines
FONT = "ui-sans-serif, system-ui, 'Segoe UI', Helvetica, Arial, sans-serif"; MONO = "ui-monospace, 'DejaVu Sans Mono', Menlo, monospace"
EV_SHORT = {'pointer:held@publish': 'held@publish', 'pointer:held@publish+source': 'held@publish + source', 'container:observed': 'container op',
            'exact:message_filters': 'message_filters', 'probe:band': 'method probe (band)', 'probe:latest': 'method probe (latest)'}


def ms(v):
    return '' if v is None else (f"{v / 1e6:.1f} ms" if v < 1e8 else f"{v / 1e9:.2f} s")


def short_ent(v):
    e = v.get('etype'); ent = str(v.get('entity') or '')
    if e == 'tmr':
        T = (v.get('arrival') or {}).get('T_cfg') or (ent.replace('timer_', '').replace('ns', '') if ent.startswith('timer_') else None)
        try: return f"timer {int(T) / 1e6:g} ms"
        except Exception: return 'timer'
    tail = [p for p in ent.split('/') if p]
    return {'sub': 'sub ', 'serv': 'srv ', 'cli': 'cli '}.get(e, (e or '') + ' ') + ('/'.join(tail[-2:]) if len(tail) > 1 else (tail[-1] if tail else ent))


def collect(d, needle):
    VN = {v['id']: v for t in d['tasks'] for v in t['vertices']}
    node_of = lambda vid: (VN.get(vid) or {}).get('node')
    nodes = sorted({v['node'] for v in VN.values() if needle in v['node']})
    if not nodes: sys.exit(f'no callback of a node matching {needle!r}')
    if len(nodes) > 1: print(f"note: {needle!r} matches {len(nodes)} nodes, taking {nodes[0]}", file=sys.stderr)
    N = nodes[0]
    before, now, unk = {}, {}, 0      # (u, v) -> dict(kind, prov, age, n)
    for c in d['candidates']:
        if node_of(c['v']) == N or node_of(c['u']) == N:
            if c['u'] in VN and c['v'] in VN: before[(c['u'], c['v'])] = dict(kind=c['nature'], prov=c.get('candidate_evidence'), age=None, n=None, cand=True)
            else: unk += 1
    for t in d['tasks']:
        for e in t['edges']:
            if e['kind'] == 'join' and e.get('n_pairs') and node_of(e['v']) == N:
                x = dict(kind='join', prov=e.get('prov'), age=(e.get('delta') or {}).get('p50'), n=e.get('n_pairs'), cand=False); before[(e['u'], e['v'])] = x; now[(e['u'], e['v'])] = x
    for s in d['sampled']:
        if s.get('method') in ('tf_lookup', 'tf_static', 'polled_take'): continue
        if node_of(s['reader_vertex']) == N and s.get('writer_vertex') in VN:
            x = dict(kind='state', prov=s.get('prov') or s.get('method'), age=s.get('age_p50'), n=s.get('n'), cand=False); before[(s['writer_vertex'], s['reader_vertex'])] = x; now[(s['writer_vertex'], s['reader_vertex'])] = x
    writers = sorted({u for u, _ in before}, key=lambda i: short_ent(VN[i])); readers = sorted({v for _, v in before}, key=lambda i: (VN[i]['etype'] != 'tmr', short_ent(VN[i])))
    return N, VN, before, now, unk, writers, readers


def box(out, x, y, v, w=None):
    w = w or BW; tmr = v['etype'] == 'tmr'
    out.append(f'<rect x="{x}" y="{y}" width="{w}" height="{BH}" rx="6" fill="{"#fbe9b8" if tmr else "#f4f4f2"}" stroke="{"#eda100" if tmr else "#b5b4ad"}" stroke-width="1.2"/>')
    out.append(f'<text x="{x + 8}" y="{y + 14}" font-size="10.5" font-family="{MONO}" fill="{INK}">{html.escape(short_ent(v)[:34])}</text>')
    C = (v.get('C') or {}).get('p50'); n = v.get('n')
    out.append(f'<text x="{x + 8}" y="{y + 27}" font-size="9" font-family="{MONO}" fill="{MUTED}">{html.escape(" · ".join(s_ for s_ in (f"C {ms(C)}" if C is not None else "", f"n {n}" if n else "") if s_))}</text>')


def panel(x0, y0, title, VN, writers, readers, edges, mode):
    """mode 'before': every pair the structural rule produced, join solid / state dashed, all grey; 'now': evidence green, candidates red dotted"""
    out = [f'<text x="{x0}" y="{y0 - 12}" font-size="12.5" font-weight="600" fill="{INK2}">{html.escape(title)}</text>']
    pw = {u: (x0, y0 + i * (BH + GY)) for i, u in enumerate(writers)}
    hR = len(readers) * (BH + GY); hW = len(writers) * (BH + GY); offR = max(0, (hW - hR) / 2)
    pr = {v: (x0 + BW + GX, y0 + offR + i * (BH + GY)) for i, v in enumerate(readers)}
    labels = []
    for (u, v), e in edges.items():
        if u not in pw or v not in pr: continue
        (xa, ya), (xb, yb) = pw[u], pr[v]; x1, y1, x2, y2 = xa + BW, ya + BH / 2, xb, yb + BH / 2
        join = 'join' in str(e['kind'])
        if mode == 'before':
            dash = '' if join else ' stroke-dasharray="6 4"'
            out.append(f'<line x1="{x1}" y1="{y1}" x2="{x2 - 1}" y2="{y2}" stroke="{INK2}" stroke-width="1.15"{dash} opacity="0.8" marker-end="url(#ah)"/>')
        elif e['cand']:
            if NOCAND: continue
            out.append(f'<line x1="{x1}" y1="{y1}" x2="{x2 - 1}" y2="{y2}" stroke="{RED}" stroke-width="0.9" stroke-dasharray="2 4" opacity="0.45"/>')
        else:
            out.append(f'<line x1="{x1}" y1="{y1}" x2="{x2 - 1}" y2="{y2}" stroke="{GREEN}" stroke-width="2.6" marker-end="url(#ahg)"/>')
            lab = f"{EV_SHORT.get(e['prov'], str(e['prov']).replace('observed:', ''))}{(' · age ' + ms(e['age'])) if e['age'] else ''}{(' · n ' + str(e['n'])) if e['n'] else ''}"
            labels.append(f'<text x="{x1 + (x2 - x1) * 0.35}" y="{y1 + (y2 - y1) * 0.35 - 7}" text-anchor="middle" font-size="10.5" font-weight="600" fill="{GREEN}" paint-order="stroke" stroke="{SURF}" stroke-width="4">{html.escape(lab)}</text>')
    for coll, pos in ((writers, pw), (readers, pr)):
        for i in coll: box(out, *pos[i], VN[i])
    return out + labels, max(hW, offR + hR)


def merge_rows(d):
    """task-level effect: the join candidates between active callbacks, applied as edges, glue data tasks together (union-find)"""
    T = {t['id']: t for t in d['tasks']}; VN = {v['id']: v for t in d['tasks'] for v in t['vertices']}; VT = {v['id']: t['id'] for t in d['tasks'] for v in t['vertices']}
    par = {t: t for t in T}

    def f(x):
        while par[x] != x: par[x] = par[par[x]]; x = par[x]
        return x
    glue = collections.defaultdict(lambda: collections.Counter())
    for c in d['candidates']:
        if c['nature'] == 'join_candidate' and c['u'] in VT and c['v'] in VT and VT[c['u']] != VT[c['v']]:
            a, b = VT[c['u']], VT[c['v']]; glue[tuple(sorted((a, b)))][VN[c['v']]['node'].rstrip('/').split('/')[-1]] += 1
            ra, rb = f(a), f(b)
            if ra != rb: par[ra] = rb
    groups = collections.defaultdict(list)
    for t in T:
        if not T[t].get('infra'): groups[f(t)].append(t)
    n_data = sum(1 for t in T.values() if not t.get('infra'))
    big = max(groups.values(), key=len)
    return T, sorted(big, key=lambda i: -T[i]['size']), glue, n_data, len(groups)


def task_label(t):
    s = t['sources'][0]['name'] if t['sources'] else t['vertices'][0]['name']
    node, _, rest = s.partition(' / ')
    ent = rest.split('→')[-1].strip() if '→' in rest else rest
    if ent.startswith('tmr:timer_'):
        try: ent = f"timer {round(int(ent[10:].replace('ns', '')) / 1e6, 1):g} ms"
        except Exception: pass
    elif '/' in ent: ent = '/'.join([p for p in ent.split('/') if p][-2:])
    return node.rstrip('/').split('/')[-1][:30], ent[:32]


def merge_panel(x0, y0, T, tasks, glue, mode, PW):
    TW, TH, TG = 300, 40, 14
    out = []; pos = {}
    for i, tid in enumerate(tasks):
        pos[tid] = (x0 + 20, y0 + 24 + i * (TH + TG))
    H = 24 + len(tasks) * (TH + TG) + 10
    if mode == 'before':
        n_cb = sum(T[t]['size'] for t in tasks)
        out.append(f'<rect x="{x0}" y="{y0}" width="{TW + 300}" height="{H}" rx="10" fill="#f4f4f2" stroke="{INK2}" stroke-width="1.6"/>')
        out.append(f'<text x="{x0 + 12}" y="{y0 + 16}" font-size="11.5" font-weight="600" fill="{INK}">ONE task · {n_cb} callbacks · {len(tasks)} sources</text>')
    PAL = [('#2a78d6', '#cde2fb'), ('#eb6834', '#fbdccf'), ('#1baf7a', '#c9efe0'), ('#eda100', '#fbe9b8'), ('#6250d6', '#dcd7f7'), ('#e87ba4', '#f9dde8'), ('#1a8fa3', '#d6f0f5'), ('#9a7b1a', '#eee5c8')]
    for i, tid in enumerate(tasks):
        x, y = pos[tid]; nm, ent = task_label(T[tid]); c, tint = PAL[i % len(PAL)]
        fill, strk = ('#ffffff', '#b5b4ad') if mode == 'before' else (tint, c)
        out.append(f'<rect x="{x}" y="{y}" width="{TW}" height="{TH}" rx="7" fill="{fill}" stroke="{strk}" stroke-width="1.4"/>')
        out.append(f'<text x="{x + 10}" y="{y + 16}" font-size="11" fill="{INK}">{html.escape(nm)} <tspan font-family="{MONO}" font-size="10" fill="{INK2}">{html.escape(ent)}</tspan></text>')
        out.append(f'<text x="{x + 10}" y="{y + 31}" font-size="9.5" font-family="{MONO}" fill="{MUTED}">task {tid} · {T[tid]["size"]} callback(s)</text>')
    # glue arcs on the right side
    k = 0; used = []
    for (a, b), nodes in sorted(glue.items(), key=lambda kv: (pos.get(kv[0][0], (0, 0))[1], pos.get(kv[0][1], (0, 0))[1])):
        if a not in pos or b not in pos or (NOCAND and mode != 'before'): continue
        (xa, ya), (xb, yb) = pos[a], pos[b]; x1 = xa + TW; y1 = ya + TH / 2; y2 = yb + TH / 2; bulge = 40 + 26 * (k % 5); k += 1
        col, dash, op = (INK2, '', 0.9) if mode == 'before' else (RED, ' stroke-dasharray="2 4"', 0.6)
        out.append(f'<path d="M{x1},{y1} C{x1 + bulge},{y1} {x1 + bulge},{y2} {x1},{y2}" fill="none" stroke="{col}" stroke-width="1.5"{dash} opacity="{op}"/>')
        lab = ', '.join(f"{n} ×{c}" for n, c in nodes.most_common(2))
        lx = x1 + bulge * 0.75 + 6; ly = (y1 + y2) / 2 + 3
        while any(abs(ly - uy) < 13 and lx < ux2 and lx + 6.2 * len(lab) > ux1 for ux1, ux2, uy in used): ly += 13   # no two labels on top of each other
        used.append((lx, lx + 6.2 * len(lab), ly))
        out.append(f'<line x1="{x1 + bulge * 0.75}" y1="{(y1 + y2) / 2}" x2="{lx - 2}" y2="{ly - 3}" stroke="{col}" stroke-width="0.6" opacity="0.6"/>')
        out.append(f'<text x="{lx}" y="{ly}" font-size="9.5" fill="{col}" paint-order="stroke" stroke="{SURF}" stroke-width="3">{html.escape(lab)}</text>')
    return out, H


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('json'); ap.add_argument('--node', action='append', required=True); ap.add_argument('-o', '--out', required=True)
    ap.add_argument('--title', default='Structural couplings before 2026-10-25 against evidence now: one node at a time, then the task set')
    ap.add_argument('--no-merge', action='store_true', help='leave out the task-level panel (data tasks glued by structural joins)')
    ap.add_argument('--no-candidates', action='store_true', help='NOW panels show the evidence edges only: no candidate lines, no candidate wording')
    a = ap.parse_args(); d = json.load(open(a.json))
    global NOCAND; NOCAND = a.no_candidates
    rows = [collect(d, n) for n in a.node]
    PW = 2 * BW + GX; GAPP = 140; W = PADX * 2 + 2 * PW + GAPP; y = PADY + 40; body = []
    for N, VN, before, now, unk, writers, readers in rows:
        n_old = len(before); n_new = len(now); n_cand = sum(1 for e in before.values() if e['cand'])
        body.append(f'<text x="{PADX}" y="{y}" font-size="16" font-weight="700" fill="{INK}">{html.escape(N)}: {n_old} edges → {n_new}</text>')
        sub_now = f"{n_new} observed with an evidence record" if NOCAND else f"{n_cand} of them stay listed as candidates (no evidence record), {n_new} observed"
        body.append(f'<text x="{PADX}" y="{y + 18}" font-size="11.5" fill="{INK2}">{html.escape(sub_now +(f"; {unk} more pairs involve a callback that ran < 5 times in the window (not drawn, never were task edges)" if unk else ""))}</text>')
        yp = y + 56
        p1, h1 = panel(PADX, yp, 'BEFORE · structural rule: every storing sub callback → every publishing callback / timer of the node', VN, writers, readers, before, 'before')
        p2, h2 = panel(PADX + PW + GAPP, yp, 'NOW · an edge only with an evidence record' + ('' if NOCAND else '; the rest are candidates'), VN, writers, readers, before, 'now')
        body += p1 + p2; y = yp + max(h1, h2) + 80
    if not a.no_merge:
        T, tasks, glue, n_data, n_groups = merge_rows(d)
        n_glue = sum(sum(c.values()) for c in glue.values())
        body.append(f'<text x="{PADX}" y="{y}" font-size="16" font-weight="700" fill="{INK}">The task set: {len(tasks)} tasks were glued into one by {n_glue} structural joins → now {len(tasks)} separate tasks</text>')
        body.append(f'<text x="{PADX}" y="{y + 18}" font-size="11.5" fill="{INK2}">{html.escape(f"data tasks {n_groups} with the structural joins as edges, {n_data} now; a task mixing the 20 ms localization timer and the 30 ms control timer has no single release pattern — not an analyzable task")}</text>')
        yp = y + 56
        q1, hq1 = merge_panel(PADX, yp, T, tasks, glue, 'before', PW)
        q2, hq2 = merge_panel(PADX + PW + GAPP, yp, T, tasks, glue, 'now', PW)
        body.append(f'<text x="{PADX}" y="{yp - 12}" font-size="12.5" font-weight="600" fill="{INK2}">BEFORE · the joins were task edges (arcs = the structural joins, labelled with the node that holds them)</text>')
        body.append(f'<text x="{PADX + PW + GAPP}" y="{yp - 12}" font-size="12.5" font-weight="600" fill="{INK2}">NOW · each task on its own' + ('' if NOCAND else '; the same couplings are listed as join candidates (dotted)') + '</text>')
        body += q1 + q2; y = yp + max(hq1, hq2) + 50
    H = y + 30
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" font-family="{FONT}">', f'<rect width="{W}" height="{H}" fill="{SURF}"/>',
           '<defs>' + ''.join(f'<marker id="{mid}" viewBox="0 0 8 8" refX="7.5" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0.5 L7.5,4 L0,7.5 z" fill="{mc}"/></marker>' for mid, mc in (('ah', INK2), ('ahr', RED), ('ahg', GREEN))) + '</defs>',
           f'<text x="{PADX}" y="36" font-size="20" font-weight="600" fill="{INK}">{html.escape(a.title)}</text>',
           f'<text x="{PADX}" y="58" font-size="12" fill="{INK2}">session {html.escape(d["session"])} · left column: subscription callbacks that store their message · right column: timers (yellow) and publishing callbacks of the same node</text>',
           f'<g font-size="11.5" fill="{INK2}"><line x1="{PADX}" y1="78" x2="{PADX + 34}" y2="78" stroke="{INK2}" stroke-width="1.3" marker-end="url(#ah)"/><text x="{PADX + 42}" y="82">structural join (task edge)</text>'
           f'<line x1="{PADX + 230}" y1="78" x2="{PADX + 264}" y2="78" stroke="{INK2}" stroke-width="1.3" stroke-dasharray="6 4" marker-end="url(#ah)"/><text x="{PADX + 272}" y="82">structural state link (assumed read)</text>'
           f'<line x1="{PADX + 520}" y1="78" x2="{PADX + 554}" y2="78" stroke="{GREEN}" stroke-width="2.6" marker-end="url(#ahg)"/><text x="{PADX + 562}" y="82">observed, with its evidence record</text>'
           + ('' if NOCAND else f'<line x1="{PADX + 800}" y1="78" x2="{PADX + 834}" y2="78" stroke="{RED}" stroke-width="1.2" stroke-dasharray="2 4"/><text x="{PADX + 842}" y="82">candidate: reported, never an edge</text>') + '</g>']
    out += body + ['</svg>']
    svg = '\n'.join(out); open(a.out + '.svg', 'w').write(svg)
    open(a.out + '.html', 'w').write(f'<!doctype html><html><head><meta charset="utf-8"><title>FISH before / after</title><style>body{{margin:0;background:#f4f4f2}} .w{{padding:16px;overflow:auto}}</style></head><body><div class="w">{svg}</div></body></html>')
    r = subprocess.run([sys.executable, os.path.join(os.path.dirname(os.path.abspath(__file__)), 'svg2png.py'), a.out + '.svg', a.out + '.png'], capture_output=True, text=True)
    for N, VN, before, now, unk, writers, readers in rows:
        print(f"{N}: before {len(before)} edges (+{unk} pairs with a rarely-run callback), now {len(now)} edge(s), {sum(1 for e in before.values() if e['cand'])} candidates; writers {len(writers)}, readers {len(readers)}")
    print(f"{a.out}.svg/.html" + ('/.png' if r.returncode == 0 else f' (png failed: {r.stderr[-120:]})') + f"  {W}x{H}")


if __name__ == '__main__':
    main()
